<section class="page"><p class="eyebrow">DISCOVER SOMETHING GREAT</p><h1>Movies & series</h1><form id="search-form" class="search-toolbar"><label class="search-field">Search titles<input name="search" id="search-input" type="search" placeholder="Arabic or English title…" maxlength="200" autocomplete="off"></label><label>Catalog or source<select name="provider" id="provider-select"><option value="">All discovered titles</option></select></label><label>Type<select name="media_type"><option value="">All types</option><option value="movie">Movies</option><option value="tv">Series</option></select></label><label>Year<input name="year" inputmode="numeric" pattern="[0-9]{4}" placeholder="Any year" maxlength="4"></label><label>Language<input name="language" placeholder="e.g. ar" maxlength="16"></label><label>Genre<input name="genre" placeholder="Name or ID" maxlength="80"></label><button class="button" type="submit">Search</button></form><p class="muted">All discovered titles searches the local normalized catalog. Choose a source to discover and import more titles.</p><p id="search-status" role="status"></p><div id="search-results" class="movie-grid"></div><button id="load-more" class="button secondary" hidden>Load more</button></section>
